tasks.answer:
calls = 0

def fib(n):
    global calls
    calls += 1
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

for n in [5, 10, 20]:
    calls = 0
    result = fib(n)
    print(f'fib({n}) = {result}, 호출 {calls}번')
